const STORAGE_KEY='doc-capa-state-v3';
const {jsPDF}=window.jspdf||{};

const INTRO={
  justification:[
    'La detección de necesidades de capacitación docente constituye un proceso estratégico fundamental para garantizar la calidad de la docencia y la mejora continua de los procesos académicos en el Instituto Superior Tecnológico Quito Metropolitano (ITSQMET). En un contexto de transformación constante de la educación superior tecnológica, caracterizado por la incorporación de nuevas metodologías, enfoques pedagógicos y exigencias del entorno profesional, resulta imprescindible identificar de manera sistemática y fundamentada las brechas de capacitación del cuerpo docente.',
    'El presente informe se justifica como un instrumento técnico-diagnóstico que permite reconocer, analizar y priorizar las necesidades reales de capacitación docente, a partir de evidencia institucional y del criterio académico de los actores directamente involucrados en los procesos formativos. Este diagnóstico se sustenta en el análisis del criterio de los coordinadores de carrera, las reuniones académicas mantenidas con los docentes y los resultados de encuestas institucionales aplicadas, lo que garantiza una aproximación contextualizada y alineada con la realidad académica de cada carrera.',
    'Asimismo, la detección de necesidades de capacitación docente responde a la necesidad de fortalecer el desempeño pedagógico en la función sustantiva de docencia, asegurando la coherencia entre los perfiles de egreso, los resultados de aprendizaje, la planificación académica y las demandas actuales del entorno educativo y profesional. La identificación de múltiples necesidades por carrera, así como la priorización de una necesidad ganadora, permite orientar de manera objetiva y estratégica las futuras acciones institucionales de capacitación docente.',
    'Desde una perspectiva de gestión académica, este informe constituye una base técnica indispensable para la toma de decisiones institucionales, la planificación del Plan Operativo Anual (POA) y la posterior formulación del Plan de Capacitación Docente, sin anticipar ni definir acciones de ejecución. De esta manera, la detección se posiciona como un insumo previo, autónomo y necesario, que respalda la planificación institucional y fortalece los procesos de aseguramiento de la calidad educativa.',
    'Finalmente, este documento se justifica también como evidencia institucional ante los procesos de evaluación externa, al demostrar que el ITSQMET desarrolla procesos sistemáticos, participativos y fundamentados para identificar las necesidades de capacitación docente, en coherencia con los criterios del modelo de evaluación de la educación superior y con los lineamientos de mejora continua de la docencia.'
  ],
  contextIntro:[
    'El contexto en el que se desarrolla la educación superior tecnológica presenta transformaciones profundas y sostenidas que inciden directamente en la práctica docente y en la gestión académica institucional. Estas transformaciones configuran nuevos escenarios formativos que demandan procesos sistemáticos de análisis y actualización del desempeño docente, particularmente en la función sustantiva de docencia.',
    'En el Instituto Superior Tecnológico Quito Metropolitano (ITSQMET), dichas transformaciones se expresan en la diversidad de carreras, campos profesionales y modalidades formativas, así como en la necesidad de garantizar la coherencia entre los perfiles de egreso, los resultados de aprendizaje y las estrategias pedagógicas aplicadas en el aula. En este marco, la detección de necesidades de capacitación docente se justifica como una respuesta institucional a los cambios del entorno educativo y profesional.',
    'A continuación, se describen los principales ejes que caracterizan el contexto institucional y las transformaciones educativas relevantes para el presente diagnóstico.'
  ],
  transformations:[
    ['1.3.1. Transformaciones pedagógicas en la docencia',['La evolución de los enfoques educativos ha impulsado una transición progresiva desde modelos tradicionales de enseñanza hacia enfoques centrados en el desarrollo de competencias y en el aprendizaje activo del estudiante. Este cambio exige que el docente incorpore metodologías que promuevan la participación, el pensamiento crítico y la aplicación práctica de los conocimientos, así como sistemas de evaluación coherentes con los resultados de aprendizaje declarados.','Estas transformaciones demandan un fortalecimiento continuo de las capacidades pedagógicas del docente, particularmente en la planificación didáctica, la selección de estrategias metodológicas y la evaluación del aprendizaje.']],
    ['1.3.2. Incorporación de tecnologías y entornos digitales',['El uso de tecnologías educativas y recursos digitales se ha consolidado como un componente estructural del proceso de enseñanza-aprendizaje. Plataformas virtuales, recursos interactivos y herramientas digitales forman parte del entorno académico cotidiano, lo que requiere que los docentes desarrollen competencias para su integración pedagógica efectiva, más allá del uso instrumental de la tecnología.','Este escenario plantea la necesidad de identificar brechas en el dominio y aplicación de herramientas digitales, así como en su articulación con los objetivos formativos de cada carrera.']],
    ['1.3.3. Cambios en el perfil del estudiantado',['El estudiantado del ITSQMET presenta características cada vez más heterogéneas en términos de trayectorias educativas, contextos socioculturales y niveles de preparación académica. Esta diversidad implica nuevos retos para la docencia, especialmente en la adaptación de estrategias metodológicas, la atención a distintos ritmos de aprendizaje y la implementación de enfoques inclusivos.','En este contexto, el fortalecimiento de la capacidad docente para responder a la diversidad estudiantil se convierte en un elemento clave para garantizar la calidad y pertinencia de la formación tecnológica.']],
    ['1.3.4. Exigencias del aseguramiento de la calidad',['El sistema de aseguramiento de la calidad de la educación superior establece criterios y estándares orientados a garantizar procesos formativos planificados, evaluables y en mejora continua. Estos requerimientos refuerzan la necesidad de contar con diagnósticos institucionales que permitan identificar, con evidencia, las necesidades de capacitación docente y sustentar las decisiones académicas.','La detección de necesidades de capacitación se inscribe, por tanto, en una lógica de cumplimiento normativo y fortalecimiento institucional, alineada con los procesos de planificación académica y los mecanismos de evaluación externa.']],
    ['1.3.5. Implicaciones institucionales para la docencia',['Las transformaciones descritas generan implicaciones directas para la docencia en el ITSQMET, entre las que se destacan la necesidad de actualización pedagógica permanente, la articulación entre teoría y práctica, y el fortalecimiento de competencias docentes alineadas con los perfiles de egreso de las carreras.','En este marco, el presente diagnóstico se orienta a identificar de manera estructurada las necesidades de capacitación docente, como un insumo técnico que permita responder de forma pertinente a las transformaciones educativas y fortalecer la calidad del proceso formativo institucional.']]
  ],
  objectivesIntro:['El presente diagnóstico de necesidades de capacitación docente tiene como finalidad orientar de manera técnica y fundamentada la identificación de las brechas existentes en la función sustantiva de docencia del Instituto Superior Tecnológico Quito Metropolitano (ITSQMET). A través de este proceso, se busca generar información confiable y contextualizada que sirva como insumo para la toma de decisiones académicas y la planificación institucional, sin anticipar acciones de ejecución.','Los objetivos del diagnóstico se estructuran en un objetivo general y un conjunto de objetivos específicos, los cuales permiten delimitar el alcance del análisis y garantizar la coherencia del proceso de detección.'],
  generalObjective:'Identificar, analizar y priorizar las necesidades de capacitación docente en las carreras ofertadas por el Instituto Superior Tecnológico Quito Metropolitano (ITSQMET), en el marco de la función sustantiva de docencia, a partir del criterio de los coordinadores de carrera, las reuniones académicas con los docentes y los resultados de encuestas institucionales, con el fin de generar un insumo técnico que sustente la planificación académica y la formulación posterior del Plan de Capacitación Docente.',
  specificObjectives:['Identificar las principales necesidades de capacitación docente en cada carrera, considerando múltiples requerimientos asociados a la práctica pedagógica y al desarrollo del proceso de enseñanza-aprendizaje.','Analizar las necesidades detectadas a partir de información cualitativa y cuantitativa obtenida mediante el criterio de los coordinadores de carrera, reuniones académicas con los docentes y encuestas institucionales aplicadas.','Priorizar una necesidad de capacitación ganadora por carrera, en función de su impacto en la mejora de la docencia, su recurrencia y su alineación con los requerimientos académicos institucionales.','Reconocer necesidades de capacitación comunes entre carreras, con el propósito de identificar tendencias institucionales y posibles líneas transversales de fortalecimiento docente.','Generar una base técnica y documentada que sirva como insumo para la planificación del Plan Operativo Anual (POA) y para la elaboración posterior del Plan de Capacitación Docente, garantizando la coherencia con los procesos de aseguramiento de la calidad.']
};

const LEGAL={
  intro:['La detección de necesidades de capacitación docente del Instituto Superior Tecnológico Quito Metropolitano (ITSQMET) se sustenta en el marco constitucional, legal, reglamentario y normativo vigente del sistema de educación superior del Ecuador, así como en la normativa interna institucional, los cuales establecen la obligación de garantizar la calidad académica mediante procesos sistemáticos de evaluación, planificación y mejora continua del desempeño docente.','El presente informe se fundamenta en las siguientes disposiciones legales:'],
  blocks:[
    {title:'Constitución de la República del Ecuador',items:['el artículo 26 establece que la educación es un derecho de las personas a lo largo de su vida y un deber ineludible del Estado, constituyéndose en un área prioritaria de la política pública y de la inversión estatal.','el artículo 27 determina que la educación se centrará en el ser humano y garantizará su desarrollo integral, promoviendo capacidades, habilidades y conocimientos pertinentes para la vida social y productiva.','el artículo 350 señala que el sistema de educación superior tiene como finalidad la formación académica y profesional con visión científica y humanista, la investigación y la innovación, bajo criterios de calidad, pertinencia y responsabilidad social.']},
    {title:'Ley Orgánica de Educación Superior (LOES)',items:['el artículo 3 establece como fines de la educación superior el desarrollo del pensamiento crítico, la formación académica y profesional de calidad y la generación de conocimiento pertinente para el desarrollo del país.','el artículo 12 dispone que las instituciones de educación superior deben garantizar procesos académicos de calidad, sustentados en mecanismos de evaluación y mejora continua.','el artículo 13, literal a), establece como una de las funciones del sistema de educación superior asegurar la calidad académica a través de procesos sistemáticos de evaluación y fortalecimiento institucional.','el artículo 155 determina que las instituciones de educación superior promoverán la formación, capacitación y actualización permanente del personal académico, en coherencia con los objetivos institucionales y las necesidades del entorno educativo y profesional.']},
    {title:'Reglamentos del Sistema de Educación Superior',items:['los reglamentos derivados de la Ley Orgánica de Educación Superior disponen que las instituciones implementen procesos de planificación académica sustentados en diagnósticos técnicos, que permitan identificar brechas formativas y necesidades de fortalecimiento del desempeño docente.','dichos reglamentos enfatizan la responsabilidad institucional de documentar los procesos de análisis y toma de decisiones relacionados con la mejora continua de la docencia.']},
    {title:'Modelo de Evaluación Externa del Consejo de Aseguramiento de la Calidad de la Educación Superior (CACES)',items:['el modelo de evaluación externa del CACES establece criterios e indicadores orientados a verificar la existencia de mecanismos institucionales para la identificación, análisis y priorización de necesidades de capacitación docente.','estos criterios exigen que las instituciones de educación superior cuenten con evidencia documentada que demuestre la planificación académica basada en diagnósticos y análisis sistemáticos del desempeño docente.','el modelo de evaluación promueve la mejora continua de la docencia como un eje fundamental de la calidad educativa.']},
    {title:'Plan Estratégico de Desarrollo Institucional (PEDI) del ITSQMET',items:['el Plan Estratégico de Desarrollo Institucional del ITSQMET define como uno de sus ejes estratégicos el fortalecimiento de la calidad académica y el desarrollo permanente del cuerpo docente.','el PEDI establece la necesidad de alinear las decisiones académicas con procesos de análisis y diagnóstico que permitan identificar oportunidades de mejora en la función sustantiva de docencia.']},
    {title:'Plan Operativo Anual (POA) del ITSQMET',items:['el Plan Operativo Anual constituye el instrumento de planificación institucional que requiere insumos técnicos previos, tales como diagnósticos de necesidades, para la definición responsable de acciones, metas e indicadores relacionados con la capacitación docente.']},
    {title:'Manual de Procesos Académicos del ITSQMET',items:['el Manual de Procesos Académicos regula los procedimientos de planificación, seguimiento y evaluación del proceso docente, estableciendo la obligatoriedad de identificar de manera sistemática las brechas formativas del personal académico.','dicho manual dispone que los procesos de capacitación y fortalecimiento docente deben sustentarse en diagnósticos previos debidamente documentados.']}
  ],
  closing:'En virtud del marco legal expuesto, el presente informe se configura como un documento técnico–diagnóstico, orientado exclusivamente a la identificación, análisis y priorización de necesidades de capacitación docente, constituyéndose en un insumo previo y obligatorio para la planificación institucional, sin generar compromisos de ejecución, asignación presupuestaria ni programación operativa.'
};

const ALIGNMENT={
  intro:['El presente apartado establece la alineación del informe de detección de necesidades de capacitación docente con los instrumentos de planificación y gestión académica del Instituto Superior Tecnológico Quito Metropolitano (ITSQMET). Su desarrollo permite evidenciar que el diagnóstico no constituye un ejercicio aislado, sino que se integra de manera coherente al sistema institucional de planificación estratégica, operativa y de aseguramiento de la calidad.','La alineación institucional garantiza que las necesidades de capacitación identificadas respondan a los objetivos estratégicos, a los procesos académicos vigentes y a los requerimientos del modelo de evaluación externa, asegurando coherencia entre diagnóstico, planificación y mejora continua. En este marco, el análisis que se presenta a continuación respalda técnicamente la toma de decisiones académicas posteriores, sin anticipar acciones de ejecución, en concordancia con el alcance diagnóstico definido para el presente informe.'],
  pedi:{title:'3.1. Vinculación con el Plan Estratégico de Desarrollo Institucional (PEDI)',intro:cfg=>[`El presente informe de detección de necesidades de capacitación docente se vincula de manera directa y explícita con el ${cfg.pedi} del Instituto Superior Tecnológico Quito Metropolitano (ITSQMET), en tanto constituye un instrumento técnico que aporta información estratégica para la toma de decisiones académicas y el fortalecimiento de la función sustantiva de docencia.`,'La relación entre este diagnóstico y el PEDI se evidencia en los siguientes aspectos:'],blocks:[['A) Alineación con los objetivos estratégicos institucionales','El PEDI establece como prioridad institucional el aseguramiento de la calidad académica y la mejora continua de los procesos formativos. La detección de necesidades de capacitación docente contribuye a este objetivo al identificar, analizar y priorizar brechas formativas del cuerpo docente que inciden directamente en el desarrollo del proceso de enseñanza-aprendizaje y en el logro de los resultados de aprendizaje de las carreras.'],['B) Fortalecimiento del talento humano docente','El PEDI reconoce al talento humano como un eje estratégico para el cumplimiento de la misión institucional. En este marco, el presente diagnóstico permite identificar necesidades concretas de capacitación docente, proporcionando una base técnica que respalda futuras acciones de fortalecimiento del desempeño pedagógico, en coherencia con las demandas académicas y profesionales de cada carrera.'],['C) Sustento técnico para la planificación institucional','La detección de necesidades de capacitación docente se constituye en un insumo estratégico para la planificación institucional, al generar información validada que alimenta los procesos de planificación operativa y académica. Este enfoque garantiza que las decisiones relacionadas con la capacitación docente se fundamenten en diagnósticos previos y no en criterios aislados o circunstanciales.'],['D) Coherencia entre planificación estratégica y gestión académica','El presente informe fortalece la articulación entre la planificación estratégica definida en el PEDI y la gestión académica cotidiana, al evidenciar que el ITSQMET implementa procesos sistemáticos para identificar oportunidades de mejora en la docencia. Esta coherencia contribuye a una gestión institucional alineada y orientada a resultados.'],['E) Aporte al aseguramiento de la calidad educativa','Desde la perspectiva del aseguramiento de la calidad, la detección de necesidades de capacitación docente respalda el cumplimiento de los lineamientos estratégicos del PEDI relacionados con la mejora continua, al demostrar que la institución cuenta con mecanismos formales para analizar el desempeño docente y sustentar decisiones académicas con base en evidencia.']],closing:'El presente informe se integra al sistema de planificación estratégica del ITSQMET como un documento técnico que fortalece la implementación del PEDI, consolidando la docencia como un eje central de la calidad educativa y de la gestión académica institucional.'},
  poa:{title:'3.2. Articulación con el Plan Operativo Anual (POA)',intro:cfg=>[`El presente informe de detección de necesidades de capacitación docente se articula de manera directa con el ${cfg.poa} del Instituto Superior Tecnológico Quito Metropolitano (ITSQMET), en tanto constituye un insumo técnico previo y necesario para la planificación responsable de las acciones institucionales orientadas al fortalecimiento de la docencia.`,'La relación entre la detección de necesidades y el POA se evidencia en los siguientes componentes:'],blocks:[['A) Insumo técnico para la planificación operativa','El POA requiere información diagnóstica que permita definir acciones, metas e indicadores con base en necesidades reales y verificables. En este sentido, la detección de necesidades de capacitación docente proporciona evidencia técnica que sustenta la formulación de actividades futuras relacionadas con el fortalecimiento del desempeño docente, evitando decisiones improvisadas o desarticuladas del contexto académico.'],['B) Priorización institucional basada en evidencia','La identificación de múltiples necesidades por carrera y la priorización de una necesidad ganadora permiten orientar la planificación operativa hacia áreas de mayor impacto académico. Esta priorización facilita que el POA concentre recursos y esfuerzos en necesidades estratégicas, alineadas con los objetivos institucionales y con la mejora de la función sustantiva de docencia.'],['C) Coherencia entre diagnóstico y programación anual','La articulación entre el presente diagnóstico y el POA garantiza la coherencia entre las fases de análisis y planificación institucional. El informe de detección define el qué se requiere fortalecer en el ámbito docente, mientras que el POA, en una fase posterior, determinará el cómo, cuándo y con qué recursos, respetando la secuencia lógica de la gestión académica.'],['D) Soporte para la definición de metas e indicadores','Los resultados de la detección de necesidades de capacitación docente constituyen una base objetiva para la definición de metas operativas e indicadores de seguimiento en el POA, particularmente aquellos relacionados con el fortalecimiento de la calidad académica y el desempeño docente.'],['E) Alineación con el principio de mejora continua','La articulación con el POA refuerza el enfoque de mejora continua institucional, al integrar el diagnóstico de necesidades dentro del ciclo de planificación, ejecución y evaluación. Este enfoque permite que las acciones futuras contempladas en el POA respondan a un proceso sistemático y documentado de análisis previo.']],closing:'El presente informe se posiciona como un componente fundamental dentro del proceso de planificación operativa del ITSQMET, asegurando que el Plan Operativo Anual incorpore acciones coherentes, pertinentes y sustentadas en la detección formal de necesidades de capacitación docente, en concordancia con los objetivos estratégicos institucionales.'},
  manual:{title:'3.3. Coherencia con el Manual de Procesos Académicos',intro:cfg=>[`El presente informe de detección de necesidades de capacitación docente guarda coherencia directa con el ${cfg.manual}, en tanto se inserta dentro de la lógica institucional de planificación, seguimiento y mejora continua de la función sustantiva de docencia.`,'El Manual de Procesos Académicos establece que las acciones relacionadas con el fortalecimiento del desempeño docente deben sustentarse en procedimientos sistemáticos, documentados y alineados a la planificación institucional. En este marco, la detección de necesidades de capacitación docente se constituye como una fase previa y obligatoria dentro del ciclo de gestión académica.','La coherencia entre el presente diagnóstico y el Manual de Procesos Académicos se evidencia en los siguientes aspectos:'],blocks:[['A) Articulación con los procesos de planificación académica','El Manual de Procesos Académicos define la planificación como un proceso estructurado que debe basarse en información técnica y análisis previos. El presente informe responde a esta disposición al identificar y priorizar necesidades de capacitación docente a partir de evidencia recopilada, constituyéndose en un insumo para la planificación académica institucional.'],['B) Vinculación con el seguimiento y evaluación del proceso docente','De acuerdo con el Manual, el seguimiento y la evaluación del proceso docente requieren identificar oportunidades de mejora en la práctica pedagógica. La detección de necesidades de capacitación docente se alinea con este enfoque, al permitir reconocer brechas formativas que afectan el desarrollo del proceso de enseñanza-aprendizaje y que requieren fortalecimiento institucional.'],['C) Sustento procedimental para la mejora continua','El Manual de Procesos Académicos promueve la mejora continua como principio transversal de la gestión académica. El presente diagnóstico aporta a este principio al establecer un mecanismo formal para analizar necesidades docentes, evitando acciones reactivas y garantizando que las decisiones institucionales se fundamenten en procesos sistemáticos y verificables.'],['D) Coherencia con los roles y responsabilidades académicas','La identificación de necesidades de capacitación docente se realiza considerando el criterio de los coordinadores de carrera y la participación del cuerpo docente, en coherencia con los roles y responsabilidades definidos en el Manual de Procesos Académicos para la gestión y mejora de la docencia.'],['E) Separación clara entre diagnóstico y ejecución','El Manual de Procesos Académicos distingue las fases de análisis, planificación y ejecución. En concordancia con esta disposición, el presente informe se limita a la detección y priorización de necesidades de capacitación docente, sin definir acciones operativas, cronogramas ni recursos, los cuales serán abordados en instrumentos posteriores de planificación.']],closing:'El presente informe se integra de manera coherente al sistema de procesos académicos del ITSQMET, fortaleciendo la gestión de la docencia mediante un diagnóstico técnico que respalda la planificación institucional y contribuye al aseguramiento de la calidad académica.'}
};

const CACES_BLOCK={
  title:'3.4. Correspondencia con los Criterios del Modelo de Evaluación Externa del CACES',
  intro:cfg=>[`La Detección de Necesidades de Capacitación Docente del Instituto Superior Tecnológico Quito Metropolitano se articula de manera directa y explícita con los criterios, subcriterios e indicadores establecidos en el ${cfg.cacesModel}, emitido por el CACES.`,'Esta correspondencia garantiza que el diagnóstico no constituya un ejercicio aislado, sino una herramienta estratégica de aseguramiento interno de la calidad, orientada a la mejora continua del desempeño institucional.'],
  sections:[
    {heading:'A) Vinculación con el Criterio Organización',paragraphs:['El diagnóstico responde principalmente al Criterio Organización, específicamente al:','Subcriterio Planificación y Desarrollo, en tanto la detección de necesidades constituye un insumo fundamental para:'],lists:[['La planificación estratégica institucional.','La toma de decisiones informadas en materia de fortalecimiento del talento humano.','La coherencia entre diagnóstico, planificación y mejora continua.'],['Analiza de forma periódica su desempeño.','Reconoce debilidades y oportunidades de mejora.','Sustenta sus acciones futuras en información objetiva y verificable.']],bridge:'En este sentido, la identificación sistemática de brechas de capacitación permite evidenciar que la institución:'},
    {heading:'B) Articulación con el Indicador de Aseguramiento Interno de la Calidad',paragraphs:['El proceso de detección de necesidades se alinea con el indicador de Aseguramiento Interno de la Calidad, al constituirse en un mecanismo preventivo y reflexivo que:'],lists:[['Evalúa el estado actual de las competencias docentes.','Anticipa riesgos académicos y pedagógicos.','Permite planificar acciones correctivas antes de que se evidencien impactos negativos en los resultados de aprendizaje.']],closing:'La detección, en este marco, cumple una función diagnóstica que fortalece la cultura institucional de evaluación y autorregulación.'},
    {heading:'C) Relación con el Criterio Profesores',paragraphs:['El diagnóstico guarda correspondencia directa con el Criterio Profesores, particularmente en lo relacionado con:','Formación académica en curso y capacitación, al identificar:'],lists:[['Necesidades de actualización disciplinar.','Requerimientos de fortalecimiento pedagógico.','Demandas asociadas al uso de tecnologías educativas y procesos de innovación docente.']],closing:'Esta identificación permite que las decisiones posteriores de capacitación se encuentren fundamentadas en evidencia y no en supuestos generales.'},
    {heading:'D) Aporte al Criterio Docencia',paragraphs:['Desde el enfoque del Criterio Docencia, la detección de necesidades contribuye indirectamente al fortalecimiento de:'],lists:[['La calidad de los programas de estudio.','El seguimiento, control y evaluación del proceso docente.','El acompañamiento pedagógico a estudiantes.']],closing:'Un cuerpo docente con necesidades claramente diagnosticadas posibilita una planificación formativa coherente con los requerimientos reales del proceso de enseñanza-aprendizaje.'},
    {heading:'E) Enfoque Preventivo y de Mejora Continua',paragraphs:['Finalmente, la correspondencia con el modelo del CACES se expresa en el carácter preventivo y prospectivo del diagnóstico, coherente con la lógica del modelo de evaluación externa, que concibe la evaluación como:'],lists:[['Un medio para orientar la mejora institucional.','Un incentivo para el desarrollo de capacidades.','Una herramienta para la toma de decisiones estratégicas sostenibles.']],closing:'En este sentido, la detección de necesidades de capacitación se consolida como un instrumento clave del sistema interno de aseguramiento de la calidad, alineado con los principios, criterios y estándares definidos por el CACES para los institutos superiores técnicos y tecnológicos.'}
  ]
};

const METHOD_TEXT={
  opening:'El proceso de detección de necesidades de capacitación docente del Instituto Superior Tecnológico Quito Metropolitano (ITSQMET) se desarrolla bajo un enfoque diagnóstico estructurado, orientado a identificar y priorizar brechas de capacitación en la función sustantiva de docencia, a partir de información empírica y del análisis del contexto académico institucional.',
  typeIntro:'El diagnóstico adopta un enfoque mixto, integrando componentes cuantitativos y cualitativos, con el fin de obtener una visión integral de las necesidades de capacitación docente.',
  quantitative:tool=>`El componente cuantitativo se sustenta en la aplicación de encuestas institucionales mediante ${tool||'la herramienta digital configurada'}, lo que permite recopilar información estructurada, medible y comparable sobre las necesidades percibidas por los docentes.`,
  qualitative:'El componente cualitativo se desarrolla a través de reuniones académicas con los docentes y la revisión de las mallas curriculares y documentos académicos, lo que posibilita profundizar en el análisis de las prácticas pedagógicas y de las particularidades propias de cada carrera.',
  level:'El nivel del diagnóstico es descriptivo y exploratorio, ya que permite describir el estado actual de las necesidades de capacitación docente y explorar áreas de mejora y requerimientos de capacitación sin intervenir en los procesos académicos ni establecer relaciones causales.',
  purpose:'La finalidad principal del presente diagnóstico es priorizar las necesidades de capacitación docente, proporcionando información técnica que permita orientar la planificación institucional y fundamentar decisiones académicas relacionadas con el fortalecimiento de la docencia.',
  unit:'La carrera constituye la unidad principal de análisis del diagnóstico, considerando al docente como fuente primaria de información. Este enfoque permite identificar múltiples necesidades de capacitación por carrera y establecer una priorización objetiva de una necesidad ganadora, de acuerdo con criterios institucionales.',
  temporal:period=>`El diagnóstico presenta un enfoque transversal, al analizar las necesidades de capacitación docente en un momento específico, correspondiente al período académico ${period}, lo que posibilita una lectura contextualizada y actual de las brechas de capacitación existentes.`,
  role:'El presente diagnóstico se concibe como un insumo técnico previo para la elaboración del Plan de Capacitación Docente, formando parte del ciclo de planificación institucional. En consecuencia, no contempla acciones de ejecución, sino que orienta la toma de decisiones académicas posteriores.',
  quality:cfg=>`El enfoque diagnóstico se articula de manera directa con el ${cfg.pedi}, el ${cfg.poa}, el ${cfg.manual} y los criterios del ${cfg.cacesModel}, contribuyendo al fortalecimiento del sistema interno de aseguramiento de la calidad y a la mejora continua de la docencia en el ITSQMET.`,
  sourcesIntro:['La detección de necesidades de capacitación docente del Instituto Superior Tecnológico Quito Metropolitano (ITSQMET) se fundamenta en un análisis sistemático de fuentes de información primarias y secundarias, seleccionadas para garantizar la validez, pertinencia y coherencia institucional del diagnóstico. Estas fuentes permiten captar tanto la percepción directa de los actores académicos como la evidencia documental que sustenta el proceso académico de las carreras.','El uso articulado de dichas fuentes asegura una comprensión integral de las brechas de capacitación existentes y evita que la identificación de necesidades se base en criterios aislados o subjetivos.'],
  complement:['El análisis de las fuentes de información se realiza bajo un enfoque mixto, combinando criterios metodológicos y procedimentales, lo que garantiza rigor técnico y coherencia institucional.','No se establece una jerarquía excluyente entre las fuentes; por el contrario, estas se analizan de manera complementaria, permitiendo contrastar información cuantitativa con evidencia cualitativa y documental.'],
  use:'Las fuentes se utilizan exclusivamente para la identificación de necesidades de capacitación docente y no como instrumentos de evaluación del desempeño.',
  useBullets:['Reconocer brechas de capacitación existentes.','Sustentar técnicamente la priorización de necesidades.','Proporcionar insumos objetivos para la planificación institucional posterior.'],
  sourcesQuality:'El uso de las fuentes de información se articula con los instrumentos institucionales vigentes y con el Modelo de Evaluación Externa del CACES. La finalidad es demostrar que la detección constituye un proceso formal, documentado y alineado con la mejora continua institucional.'
};

const SOURCE_DEFS={
  surveys:{label:'Encuestas institucionales',sheet:'Encuestas',required:['CARRERA','NECESIDAD'],columns:['CARRERA','NECESIDAD','RESPUESTA','ID_DOCENTE'],description:'Se aplicaron encuestas institucionales mediante formularios digitales con el objetivo de recopilar información cuantificable sobre las necesidades de capacitación docente.',bullets:['Identificar áreas recurrentes de fortalecimiento pedagógico y disciplinar.','Obtener datos comparables entre carreras.','Sistematizar resultados que facilitan el análisis global e institucional.']},
  meetings:{label:'Reuniones académicas con docentes',sheet:'Reuniones',required:['CARRERA','NECESIDAD'],columns:['CARRERA','FECHA_REUNION','NECESIDAD','OBSERVACION'],description:'Las reuniones académicas permitieron profundizar cualitativamente en los resultados de las encuestas, recogiendo aportes reflexivos y experiencias directas del cuerpo docente.',bullets:['Contextualizar las necesidades identificadas.','Analizar problemáticas específicas por carrera.','Contrastar percepciones individuales con dinámicas académicas colectivas.']},
  coordinators:{label:'Criterio del coordinador de carrera',sheet:'Coordinadores',required:['CARRERA','COORDINADOR','NECESIDAD_VALIDADA'],columns:['CARRERA','COORDINADOR','NECESIDAD_VALIDADA','CRITERIO_COORDINADOR','OBSERVACION_COORDINADOR','DESEMPATE_REQUERIDO'],description:'El criterio del coordinador de carrera se considera una fuente primaria estratégica, al aportar una visión integral del desempeño docente, del cumplimiento curricular y de las necesidades de capacitación desde la gestión académica.',bullets:['Validar la información levantada con docentes.','Identificar necesidades prioritarias desde una perspectiva institucional.','Contribuir a la toma de decisiones para la priorización de necesidades por carrera.']},
  curricula:{label:'Mallas curriculares',sheet:'Mallas',required:['CARRERA','NECESIDAD'],columns:['CARRERA','NECESIDAD','HALLAZGO','EVIDENCIA_MALLA'],description:'La revisión de las mallas curriculares permitió identificar requerimientos asociados a los perfiles de egreso, las competencias profesionales declaradas y las demandas actuales del campo profesional de cada carrera.',bullets:['Perfiles de egreso.','Competencias profesionales declaradas.','Demandas actuales del campo profesional de cada carrera.']},
  peas:{label:'Planes de Enseñanza–Aprendizaje (PEA)',sheet:'PEA',required:['CARRERA','NECESIDAD'],columns:['CARRERA','NECESIDAD','HALLAZGO','EVIDENCIA_PEA'],description:'El análisis de los PEA permitió evaluar la coherencia entre contenidos, metodologías, resultados de aprendizaje y estrategias de evaluación. A partir de esta revisión se identificaron posibles brechas que requieren fortalecimiento docente, particularmente en aspectos metodológicos y didácticos.',bullets:[]}
};

function defaultConfig(){return{pedi:'Plan Estratégico de Desarrollo Institucional (PEDI)',poa:'Plan Operativo Anual (POA)',manual:'Manual de Procesos Académicos del Instituto Superior Tecnológico Quito Metropolitano (ITSQMET)',cacesModel:'Modelo de Evaluación Externa 2024 con fines de acreditación para los Institutos Superiores Técnicos y Tecnológicos',cacesYear:'2024',cacesValidated:true,surveyTool:'Microsoft Forms'};}
function defaultState(){return{period:null,careers:[],logo:null,dncStatus:'draft',institutionalConfig:defaultConfig(),methodologyImages:{diagnostic:null,sources:null},sources:{surveys:[],meetings:[],coordinators:[],curricula:[],peas:[]},candidates:[]};}
function loadState(){try{const saved=JSON.parse(localStorage.getItem(STORAGE_KEY))||{};return{...defaultState(),...saved,institutionalConfig:{...defaultConfig(),...(saved.institutionalConfig||{})},methodologyImages:{diagnostic:null,sources:null,...(saved.methodologyImages||{})},sources:{surveys:[],meetings:[],coordinators:[],curricula:[],peas:[],...(saved.sources||{})}};}catch{return defaultState();}}
const state=loadState();
function saveState(){localStorage.setItem(STORAGE_KEY,JSON.stringify(state));renderAll();}
function escapeHtml(v){return String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#039;','"':'&quot;'}[c]));}
function normalized(v){return String(v??'').trim().toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');}
function boolValue(v){return['si','sí','yes','1','true','x'].includes(normalized(v));}
function monthLabel(value){if(!value)return'';const[y,m]=value.split('-').map(Number),names=['enero','febrero','marzo','abril','mayo','junio','julio','agosto','septiembre','octubre','noviembre','diciembre'];return`${names[m-1]} ${y}`;}
function periodLabel(){return state.period?`${monthLabel(state.period.start)} – ${monthLabel(state.period.end)}`:'Sin período activo';}
function activeCareers(){return state.careers.filter(c=>c.active!==false);}
function sourceNeed(row,key){return key==='coordinators'?row.NECESIDAD_VALIDADA:row.NECESIDAD;}
function evidenceCareerNames(){const set=new Set();Object.entries(state.sources).forEach(([key,rows])=>rows.forEach(r=>{if(r.CARRERA)set.add(normalized(r.CARRERA));}));return set;}
function evidenceCareers(){const set=evidenceCareerNames();return activeCareers().filter(c=>set.has(normalized(c.name)));}
function coverageInfo(){const total=activeCareers().length,covered=evidenceCareers().length;if(!total)return{total:0,covered:0,pct:null,status:'pending',phrase:'las carreras incluidas en el proceso de detección de necesidades de capacitación'};const pct=Math.round((covered/total)*100);if(covered===total&&total>0)return{total,covered,pct,status:'complete',phrase:'las carreras ofertadas por el ITSQMET'};if(covered>0)return{total,covered,pct,status:'partial',phrase:'las carreras incluidas en el proceso de detección de necesidades de capacitación correspondiente al período'};return{total,covered:0,pct:0,status:'pending',phrase:'las carreras incluidas en el proceso de detección de necesidades de capacitación'};}
function introScopeParagraphs(){const period=state.period?periodLabel():'[PERÍODO ACADÉMICO PENDIENTE]',coverage=coverageInfo();return[`El presente informe de detección de necesidades de capacitación docente se desarrolla para el período académico ${period}, considerado un momento estratégico dentro del ciclo de planificación, seguimiento y mejora continua de la docencia en el Instituto Superior Tecnológico Quito Metropolitano (ITSQMET). Este período permite analizar de manera pertinente las condiciones reales del ejercicio docente, las prácticas pedagógicas implementadas y las brechas de capacitación evidenciadas durante el desarrollo académico institucional.`,'El alcance temporal del diagnóstico no se limita a una revisión puntual, sino que recoge información acumulada y validada a partir de la experiencia docente inmediata, las observaciones académicas realizadas durante el desarrollo de las asignaturas y la reflexión pedagógica generada en los espacios de coordinación y trabajo colegiado. De esta manera, la detección responde a necesidades actuales y contextualizadas, evitando enfoques aislados o desarticulados de la realidad institucional.',`En cuanto a la cobertura, el informe abarca ${coverage.phrase}, considerando a los docentes y coordinadores de carrera como actores clave en la identificación de necesidades de capacitación. La detección se realiza exclusivamente desde la función sustantiva de docencia, enfocándose en los procesos de planificación académica, desarrollo de clases, evaluación del aprendizaje, uso de metodologías y fortalecimiento de competencias pedagógicas vinculadas al perfil de egreso de cada carrera.`,'La cobertura del diagnóstico se estructura a nivel de carrera, permitiendo identificar múltiples necesidades de capacitación docente, sustentadas en evidencia cualitativa y cuantitativa. A partir de este análisis, se prioriza una necesidad ganadora por carrera, definida como aquella que presenta mayor impacto en la mejora de la docencia y mayor recurrencia según los criterios establecidos. Asimismo, el informe contempla la agrupación de carreras que comparten una misma necesidad de capacitación, lo que posibilita una visión institucional integrada y coherente de las brechas identificadas.','Este enfoque de cobertura permite, además, identificar tendencias transversales, necesidades recurrentes y áreas críticas comunes, sin perder la especificidad disciplinar de cada carrera. De esta forma, el informe aporta información estratégica tanto a nivel particular como institucional, fortaleciendo los procesos de toma de decisiones académicas.','Es importante precisar que el alcance del presente documento se circunscribe estrictamente a la fase de detección y análisis de necesidades, constituyéndose como un insumo técnico previo para la planificación institucional. En consecuencia, no contempla la definición de programas de capacitación, cronogramas, modalidades, cargas horarias ni estrategias de ejecución, los cuales serán desarrollados posteriormente en el Plan de Capacitación Docente, una vez validados los resultados de esta detección.'];}

function renderIntroHtml(){let h='<h2>1. Introducción</h2><h3>1.1. Justificación del Informe</h3>'+INTRO.justification.map(p=>`<p>${escapeHtml(p)}</p>`).join('');h+='<h3>1.2. Alcance Temporal y Cobertura</h3>'+introScopeParagraphs().map(p=>`<p>${escapeHtml(p)}</p>`).join('');h+='<h3>1.3. Contexto Institucional y Transformaciones Educativas</h3>'+INTRO.contextIntro.map(p=>`<p>${escapeHtml(p)}</p>`).join('');INTRO.transformations.forEach(([t,ps])=>h+=`<h4>${escapeHtml(t)}</h4>${ps.map(p=>`<p>${escapeHtml(p)}</p>`).join('')}`);h+='<h3>1.4. Objetivos del Diagnóstico</h3>'+INTRO.objectivesIntro.map(p=>`<p>${escapeHtml(p)}</p>`).join('')+`<h4>1.4.1. Objetivo General</h4><p>${escapeHtml(INTRO.generalObjective)}</p><h4>1.4.2. Objetivos Específicos</h4><ol class="alpha" type="a">${INTRO.specificObjectives.map(x=>`<li>${escapeHtml(x)}</li>`).join('')}</ol>`;return h;}
function renderLegalHtml(){let h='<h2>2. Base Legal</h2>'+LEGAL.intro.map(p=>`<p>${escapeHtml(p)}</p>`).join('');LEGAL.blocks.forEach(b=>{h+=`<div class="legal-block"><div class="legal-block-title">${escapeHtml(b.title)}</div>${b.items.map(i=>`<div class="considerando"><em>Que,</em><span>${escapeHtml(i)}</span></div>`).join('')}</div>`;});return h+`<p>${escapeHtml(LEGAL.closing)}</p>`;}
function renderStandardAlignmentBlock(block,cfg){return `<h3>${escapeHtml(block.title)}</h3>${block.intro(cfg).map(p=>`<p>${escapeHtml(p)}</p>`).join('')}${block.blocks.map(([t,p])=>`<h4>${escapeHtml(t)}</h4><p>${escapeHtml(p)}</p>`).join('')}<p>${escapeHtml(block.closing)}</p>`;}
function emphasizeCaces(text){const terms=['Criterio Organización','Subcriterio Planificación y Desarrollo','Aseguramiento Interno de la Calidad','Criterio Profesores','Formación académica en curso y capacitación','Criterio Docencia'];let out=escapeHtml(text);terms.forEach(t=>{out=out.replaceAll(escapeHtml(t),`<strong>${escapeHtml(t)}</strong>`);});return out;}
function renderAlignmentHtml(){const cfg=state.institutionalConfig;let h='<h2>3. Alineación Institucional</h2>'+ALIGNMENT.intro.map(p=>`<p>${escapeHtml(p)}</p>`).join('');h+=renderStandardAlignmentBlock(ALIGNMENT.pedi,cfg)+renderStandardAlignmentBlock(ALIGNMENT.poa,cfg)+renderStandardAlignmentBlock(ALIGNMENT.manual,cfg);h+=`<h3>${escapeHtml(CACES_BLOCK.title)}</h3>${CACES_BLOCK.intro(cfg).map(p=>`<p>${escapeHtml(p)}</p>`).join('')}`;CACES_BLOCK.sections.forEach(s=>{h+=`<h4>${escapeHtml(s.heading)}</h4>`;s.paragraphs.forEach(p=>h+=`<p>${emphasizeCaces(p)}</p>`);if(s.lists?.[0])h+=`<ul class="method-list">${s.lists[0].map(x=>`<li>${escapeHtml(x)}</li>`).join('')}</ul>`;if(s.bridge){h+=`<p>${escapeHtml(s.bridge)}</p>`;if(s.lists?.[1])h+=`<ul class="method-list">${s.lists[1].map(x=>`<li>${escapeHtml(x)}</li>`).join('')}</ul>`;}if(s.closing)h+=`<p>${escapeHtml(s.closing)}</p>`;});return h;}

function figureHtml(kind,label){const src=state.methodologyImages[kind];return src?`<div class="method-figure"><img src="${src}" alt="${escapeHtml(label)}"></div>`:`<div class="method-figure"><div><strong>${escapeHtml(label)}</strong><br><span>Imagen fija de plantilla pendiente de configurar.</span></div></div>`;}
function hasSource(key){return(state.sources[key]||[]).length>0;}
function sourceAvailabilityText(key){return hasSource(key)?'Fuente utilizada en el período.':'No se incorpora como fuente utilizada en el período porque no existe evidencia cargada.';}
function renderSourceBlock(key,number){const d=SOURCE_DEFS[key],used=hasSource(key);let h=`<h4>${number}. ${escapeHtml(d.label)}</h4>`;if(!used)return h+`<p><em>${escapeHtml(sourceAvailabilityText(key))}</em></p>`;h+=`<p>${escapeHtml(d.description)}</p>`;if(d.bullets.length)h+=`<ul class="method-list">${d.bullets.map(x=>`<li>${escapeHtml(x)}</li>`).join('')}</ul>`;if(key==='surveys')h+='<p>La información obtenida a través de este instrumento constituye la base cuantitativa del diagnóstico.</p>';return h;}
function renderMethodHtml(){const cfg=state.institutionalConfig,period=state.period?periodLabel():'[PERÍODO ACADÉMICO PENDIENTE]';let h='<h2>4. Metodología del Diagnóstico</h2>'+figureHtml('diagnostic','Imagen ilustrativa fija de diagnóstico');h+='<h3>4.1. Enfoque Diagnóstico de la Investigación</h3><p>'+escapeHtml(METHOD_TEXT.opening)+'</p>';h+='<h4>A) Tipo de enfoque</h4><p>'+escapeHtml(METHOD_TEXT.typeIntro)+'</p><ul class="method-list"><li>'+escapeHtml(METHOD_TEXT.quantitative(cfg.surveyTool))+'</li><li>'+escapeHtml(METHOD_TEXT.qualitative)+'</li></ul>';h+='<h4>B) Nivel del estudio</h4><p>'+escapeHtml(METHOD_TEXT.level)+'</p><h4>C) Finalidad del diagnóstico</h4><p>'+escapeHtml(METHOD_TEXT.purpose)+'</p><h4>D) Unidad de análisis</h4><p>'+escapeHtml(METHOD_TEXT.unit)+'</p><h4>E) Temporalidad</h4><p>'+escapeHtml(METHOD_TEXT.temporal(period))+'</p><h4>F) Rol del diagnóstico en el ciclo institucional</h4><p>'+escapeHtml(METHOD_TEXT.role)+'</p><h4>G) Articulación con la planificación y aseguramiento de la calidad</h4><p>'+escapeHtml(METHOD_TEXT.quality(cfg))+'</p>';
  h+='<h3>4.2. Fuentes de Información</h3>'+METHOD_TEXT.sourcesIntro.map(p=>`<p>${escapeHtml(p)}</p>`).join('')+figureHtml('sources','Imagen ilustrativa fija de fuentes de información');
  h+='<h4>A) Fuentes primarias</h4>'+renderSourceBlock('surveys',1)+renderSourceBlock('meetings',2)+renderSourceBlock('coordinators',3);
  h+='<h4>B) Fuentes secundarias</h4>'+renderSourceBlock('curricula',1)+renderSourceBlock('peas',2);
  h+='<h4>C) Enfoque de análisis y complementariedad de fuentes</h4>'+METHOD_TEXT.complement.map(p=>`<p>${escapeHtml(p)}</p>`).join('');
  h+='<h4>D) Uso de las fuentes en el proceso diagnóstico</h4><p>'+escapeHtml(METHOD_TEXT.use)+'</p><ul class="method-list">'+METHOD_TEXT.useBullets.map(x=>`<li>${escapeHtml(x)}</li>`).join('')+'</ul><h4>E) Articulación institucional y aseguramiento de la calidad</h4><p>'+escapeHtml(METHOD_TEXT.sourcesQuality)+'</p>';
  h+='<h3>4.2.1. Criterio del Coordinador de Carrera</h3>'+(hasSource('coordinators')?'<p>El criterio del coordinador se utiliza para contrastar información, validar necesidades, aportar perspectiva de gestión académica, ponderar las necesidades y apoyar procesos de desempate cuando corresponda. No sustituye los datos cuantitativos ni puede utilizarse de forma unilateral.</p><ul class="method-list"><li>No reemplaza los datos de encuestas.</li><li>Se basa en evidencia académica.</li><li>Complementa otras fuentes.</li><li>Puede validar o apoyar un desempate.</li><li>No selecciona arbitrariamente una necesidad.</li></ul>':`<p><em>${escapeHtml(sourceAvailabilityText('coordinators'))}</em></p>`);
  h+='<h3>4.2.2. Reuniones Académicas con Docentes</h3>'+(hasSource('meetings')?'<p>Las reuniones académicas sirven para recopilar información cualitativa y contextualizar las necesidades identificadas.</p><ul class="method-list"><li>Metodologías de enseñanza.</li><li>Actualización disciplinar y pedagógica.</li><li>Dificultades en la implementación de los PEA.</li><li>Necesidades relacionadas con herramientas y recursos educativos.</li></ul>':`<p><em>${escapeHtml(sourceAvailabilityText('meetings'))}</em></p>`);
  h+='<h3>4.2.3. Encuestas Institucionales</h3>'+(hasSource('surveys')?`<p>Las encuestas institucionales constituyen una fuente primaria fundamental dentro del proceso de detección de necesidades de capacitación docente del Instituto Superior Tecnológico Quito Metropolitano (ITSQMET). Estas fueron aplicadas mediante la herramienta digital <strong>${escapeHtml(cfg.surveyTool)}</strong>, lo que permitió una recolección de información estructurada, sistemática y estandarizada.</p>`:`<p><em>${escapeHtml(sourceAvailabilityText('surveys'))}</em></p>`);
  h+='<h3>4.3. Criterios para la Identificación y Priorización de Necesidades</h3><h4>A) Identificación de necesidades de capacitación</h4><p>Por cada carrera se identifican cinco necesidades de capacitación obtenidas del análisis integrado de las fuentes disponibles.</p><ol><li>Encuestas institucionales.</li><li>Reuniones académicas con docentes.</li><li>Mallas curriculares.</li><li>Planes de Enseñanza–Aprendizaje (PEA).</li><li>Criterio del coordinador.</li></ol><h4>B) Priorización de la necesidad ganadora</h4><p>Las cinco necesidades se analizan considerando:</p><ul class="method-list"><li>Impacto en la calidad de la docencia.</li><li>Pertinencia con la carrera.</li><li>Recurrencia de la necesidad.</li><li>Alineación institucional.</li></ul><p>El procedimiento no establece una fórmula matemática ni pesos numéricos específicos; por tanto, la aplicación no utiliza una ponderación inventada.</p><h4>C) Nivel de aplicación de la priorización</h4><p>La priorización se realiza por carrera. Posteriormente, los resultados pueden consolidarse para identificar recurrencias institucionales.</p><h4>D) Naturaleza de los criterios</h4><p>Los criterios buscan garantizar rigurosidad metodológica, coherencia con los procesos académicos y sustento para la planificación posterior.</p><h4>E) Vinculación con la planificación institucional</h4><p>La priorización produce un insumo para el Plan de Capacitación Docente y no define todavía curso, fecha, modalidad, presupuesto, capacitador, carga horaria ni ejecución.</p>';
  h+='<h3>4.4. Procedimiento para la Selección de la Necesidad Ganadora</h3><h4>A) Identificación preliminar de necesidades por carrera</h4><p>Fuentes disponibles → análisis → cinco necesidades candidatas.</p><h4>B) Sistematización y contraste de información</h4><p>Cada necesidad debe relacionarse con evidencia proveniente de una o más fuentes. La aplicación evita cerrar como candidata una necesidad sin evidencia asociada.</p><h4>C) Análisis del impacto académico</h4><p>Cada necesidad se analiza considerando su incidencia en el proceso de enseñanza-aprendizaje, el logro de resultados de aprendizaje y la coherencia curricular y metodológica de la carrera.</p><h4>D) Validación académica</h4><p>La necesidad preliminar prioritaria se somete a validación mediante el criterio del coordinador de carrera. La aplicación no permite cerrar una necesidad como ganadora si la validación permanece pendiente o es negativa.</p><h4>E) Selección de la necesidad ganadora</h4><p>Después del análisis y validación, la necesidad ganadora debe reunir mayor impacto académico, pertinencia curricular y alineación institucional, de acuerdo con el procedimiento institucional.</p><h4>F) Registro del resultado del procedimiento</h4><p>La aplicación almacena la necesidad ganadora asociada al período y a la carrera para utilizarla posteriormente como insumo del Plan de Capacitación Docente.</p>';
  return h;
}

function evidenceForNeed(career,need){const c=normalized(career),n=normalized(need),found=[];Object.entries(state.sources).forEach(([key,rows])=>{const matches=rows.filter(r=>normalized(r.CARRERA)===c&&normalized(sourceNeed(r,key))===n);if(matches.length)found.push({key,label:SOURCE_DEFS[key].label,count:matches.length});});return found;}
function candidateRecurrence(row){const ev=evidenceForNeed(row.CARRERA,row.NOMBRE_NECESIDAD);return{sources:ev.length,occurrences:ev.reduce((a,b)=>a+b.count,0),labels:ev.map(x=>x.label)};}
function careerCandidates(career){return state.candidates.filter(x=>normalized(x.CARRERA)===normalized(career));}
function winnerForCareer(career){return careerCandidates(career).find(x=>x.GANADORA===true);}
function candidatesStatusIssues(){const issues=[];activeCareers().forEach(c=>{const rows=careerCandidates(c.name);if(rows.length!==5)issues.push(`${c.name}: debe tener exactamente 5 necesidades candidatas (actual: ${rows.length}).`);rows.forEach(r=>{if(!evidenceForNeed(r.CARRERA,r.NOMBRE_NECESIDAD).length)issues.push(`${c.name}: "${r.NOMBRE_NECESIDAD}" no tiene evidencia asociada.`);});const prelim=rows.filter(r=>r.PRELIMINAR===true);if(prelim.length!==1)issues.push(`${c.name}: debe existir una sola necesidad preliminar prioritaria.`);const winners=rows.filter(r=>r.GANADORA===true);if(winners.length!==1)issues.push(`${c.name}: debe existir una sola necesidad ganadora.`);if(winners[0]&&normalized(winners[0].VALIDACION_COORDINADOR)!=='si')issues.push(`${c.name}: la ganadora requiere VALIDACION_COORDINADOR = SI.`);if(winners[0]&&!winners[0].PRELIMINAR)issues.push(`${c.name}: la ganadora debe corresponder a la necesidad preliminar validada.`);});return issues;}
function sourceCompletenessIssues(){const issues=[];Object.keys(SOURCE_DEFS).forEach(key=>{if(!hasSource(key))issues.push(`Falta cargar la fuente: ${SOURCE_DEFS[key].label}.`);});activeCareers().forEach(c=>{Object.keys(SOURCE_DEFS).forEach(key=>{if(!state.sources[key].some(r=>normalized(r.CARRERA)===normalized(c.name)))issues.push(`${c.name}: no registra evidencia en ${SOURCE_DEFS[key].label}.`);});});return issues;}
function validateDncForFinal(){const errors=[],cov=coverageInfo();if(!state.period)errors.push('No existe un período activo.');if(!activeCareers().length)errors.push('No existen carreras activas cargadas para el período.');if(cov.status!=='complete')errors.push('La cobertura del diagnóstico todavía no está completa.');if(LEGAL.blocks.length!==7)errors.push('La Base Legal maestra no contiene los 7 bloques esperados.');if(!state.institutionalConfig.cacesValidated)errors.push('El bloque CACES vigente no está validado.');if(!state.methodologyImages.diagnostic)errors.push('Falta la imagen fija de diagnóstico de la Sección 4.');if(!state.methodologyImages.sources)errors.push('Falta la imagen fija de fuentes de la Sección 4.');errors.push(...sourceCompletenessIssues(),...candidatesStatusIssues());return [...new Set(errors)];}

function renderCandidatesTable(){const body=document.getElementById('candidatesTableBody');if(!state.candidates.length){body.innerHTML='<tr><td colspan="10" class="empty">Sin necesidades candidatas cargadas.</td></tr>';return;}const locked=state.dncStatus==='approved';body.innerHTML=state.candidates.map((r,i)=>{const rec=candidateRecurrence(r),sources=rec.labels.length?rec.labels.join(', '):'Sin evidencia';return`<tr data-ci="${i}"><td>${escapeHtml(r.CARRERA)}</td><td><input class="need-input cand-field" data-field="NOMBRE_NECESIDAD" value="${escapeHtml(r.NOMBRE_NECESIDAD)}" ${locked?'disabled':''}></td><td>${escapeHtml(sources)}</td><td>${rec.sources} fuente(s) / ${rec.occurrences} coincidencia(s)</td><td>${selectHtml(i,'IMPACTO_ACADEMICO',r.IMPACTO_ACADEMICO,locked)}</td><td>${selectHtml(i,'PERTINENCIA_CURRICULAR',r.PERTINENCIA_CURRICULAR,locked)}</td><td>${selectHtml(i,'ALINEACION_INSTITUCIONAL',r.ALINEACION_INSTITUCIONAL,locked)}</td><td><input type="checkbox" class="cand-check" data-field="PRELIMINAR" ${r.PRELIMINAR?'checked':''} ${locked?'disabled':''}></td><td>${validationSelectHtml(r.VALIDACION_COORDINADOR,locked)}</td><td><input type="checkbox" class="cand-check" data-field="GANADORA" ${r.GANADORA?'checked':''} ${locked?'disabled':''}></td></tr>`;}).join('');body.querySelectorAll('.cand-field').forEach(el=>el.addEventListener('change',onCandidateFieldChange));body.querySelectorAll('.cand-check').forEach(el=>el.addEventListener('change',onCandidateCheckChange));body.querySelectorAll('.validation-select').forEach(el=>el.addEventListener('change',onCandidateValidationChange));}
function selectHtml(i,field,value,locked){const options=['Pendiente','Alto','Medio','Bajo'];return`<select class="cand-field" data-field="${field}" ${locked?'disabled':''}>${options.map(o=>`<option ${normalized(value||'Pendiente')===normalized(o)?'selected':''}>${o}</option>`).join('')}</select>`;}
function validationSelectHtml(value,locked){const options=['Pendiente','SI','NO'];return`<select class="validation-select" ${locked?'disabled':''}>${options.map(o=>`<option ${normalized(value||'Pendiente')===normalized(o)?'selected':''}>${o}</option>`).join('')}</select>`;}
function rowCandidateIndex(el){return Number(el.closest('tr').dataset.ci);}
function onCandidateFieldChange(e){if(state.dncStatus==='approved')return;const i=rowCandidateIndex(e.target),f=e.target.dataset.field;state.candidates[i][f]=e.target.value.trim();saveState();}
function onCandidateValidationChange(e){if(state.dncStatus==='approved')return;const i=rowCandidateIndex(e.target);state.candidates[i].VALIDACION_COORDINADOR=e.target.value;if(normalized(e.target.value)!=='si')state.candidates[i].GANADORA=false;saveState();}
function onCandidateCheckChange(e){if(state.dncStatus==='approved')return;const i=rowCandidateIndex(e.target),field=e.target.dataset.field,row=state.candidates[i];if(field==='PRELIMINAR'&&e.target.checked){state.candidates.filter(x=>normalized(x.CARRERA)===normalized(row.CARRERA)).forEach(x=>x.PRELIMINAR=false);row.PRELIMINAR=true;}else if(field==='PRELIMINAR'){row.PRELIMINAR=false;row.GANADORA=false;}else if(field==='GANADORA'&&e.target.checked){if(!row.PRELIMINAR||normalized(row.VALIDACION_COORDINADOR)!=='si'){toast('La ganadora debe ser la preliminar y estar validada por el coordinador.');e.target.checked=false;return;}state.candidates.filter(x=>normalized(x.CARRERA)===normalized(row.CARRERA)).forEach(x=>x.GANADORA=false);row.GANADORA=true;}else row.GANADORA=false;saveState();}

function renderAll(){
  const cfg=state.institutionalConfig,cov=coverageInfo(),active=activeCareers(),covered=evidenceCareers();
  document.getElementById('activePeriodChip').textContent=state.period?periodLabel():'Sin período activo';document.getElementById('homePeriodName').textContent=state.period?periodLabel():'No configurado';document.getElementById('introPeriod').textContent=state.period?periodLabel():'Pendiente';document.getElementById('homeCareersCount').textContent=active.length;document.getElementById('homeDiagnosedCount').textContent=covered.length;document.getElementById('homeCoverage').textContent=cov.pct==null?'—':`${cov.pct}%`;document.getElementById('introActiveCareers').textContent=active.length;document.getElementById('introCoverage').textContent=cov.status==='complete'?'Completa':cov.status==='partial'?'Parcial':'Pendiente';
  document.getElementById('periodStatusDot').className=`dot${state.period?' ok':''}`;document.getElementById('periodStatusText').textContent=state.period?'Período configurado':'Período pendiente';document.getElementById('coverageStatusDot').className=`dot${cov.status==='complete'?' ok':''}`;document.getElementById('coverageStatusText').textContent=cov.status==='complete'?'Cobertura completa':cov.status==='partial'?`Cobertura parcial (${cov.covered}/${cov.total})`:'Cobertura pendiente';
  if(state.period){document.getElementById('periodStart').value=state.period.start;document.getElementById('periodEnd').value=state.period.end;document.getElementById('periodSummary').textContent=`Período activo: ${periodLabel()}`;}
  const tbody=document.getElementById('careersTableBody');document.getElementById('careersTableCaption').textContent=`${state.careers.length} registro(s)`;tbody.innerHTML=state.careers.length?state.careers.map(c=>`<tr><td>${escapeHtml(c.code||'—')}</td><td>${escapeHtml(c.name)}</td><td>${c.active===false?'No':'Sí'}</td></tr>`).join(''):'<tr><td colspan="3" class="empty">Sin registros.</td></tr>';
  document.getElementById('introPreview').innerHTML=renderIntroHtml();document.getElementById('legalPreview').innerHTML=renderLegalHtml();document.getElementById('legalList').innerHTML=LEGAL.blocks.map((b,i)=>`<div class="legal-item"><strong>${i+1}. ${escapeHtml(b.title)}</strong><span>${b.items.length} considerando(s)</span></div>`).join('');document.getElementById('alignmentPreview').innerHTML=renderAlignmentHtml();document.getElementById('methodPreview').innerHTML=renderMethodHtml();
  document.getElementById('alignPediStatus').textContent=cfg.pedi?'Configurado':'Pendiente';document.getElementById('alignPoaStatus').textContent=cfg.poa?'Configurado':'Pendiente';document.getElementById('alignCacesStatus').textContent=cfg.cacesValidated?'Validado':'Requiere validación';document.getElementById('alignCacesModel').textContent=cfg.cacesModel||'Sin modelo';document.getElementById('methodSurveyTool').textContent=cfg.surveyTool||'Pendiente';const sourceCount=Object.keys(SOURCE_DEFS).filter(hasSource).length;document.getElementById('methodSourcesCount').textContent=`${sourceCount}/5`;document.getElementById('methodCareerEvidenceCount').textContent=covered.length;
  Object.keys(SOURCE_DEFS).forEach(key=>{const b=document.getElementById(`badge-${key}`);if(b){b.textContent=`${state.sources[key].length} registro(s)`;b.className=`source-badge${state.sources[key].length?' ok':''}`;}});
  renderCandidatesTable();
  ['configPedi','configPoa','configManual','configCacesModel','configCacesYear','configSurveyTool'].forEach(id=>{const map={configPedi:'pedi',configPoa:'poa',configManual:'manual',configCacesModel:'cacesModel',configCacesYear:'cacesYear',configSurveyTool:'surveyTool'};document.getElementById(id).value=cfg[map[id]]||'';});document.getElementById('cacesValidationNotice').textContent=cfg.cacesValidated?`Bloque CACES validado para: ${cfg.cacesModel}`:'El modelo CACES cambió o no está validado. Revisa criterios/subcriterios antes de validar.';
  renderImagePreview('logoPreview',state.logo,'Sin logotipo cargado');renderImagePreview('methodImageDiagnosticPreview',state.methodologyImages.diagnostic,'Sin imagen configurada');renderImagePreview('methodImageSourcesPreview',state.methodologyImages.sources,'Sin imagen configurada');
  const approved=state.dncStatus==='approved',banner=document.getElementById('dncLockBanner');banner.className=`lock-banner${approved?' locked':''}`;document.getElementById('dncStatusText').textContent=approved?'DNC aprobada y cerrada':'DNC en borrador';document.getElementById('dncStatusHelp').textContent=approved?'Para modificar datos primero debes reabrir el documento.':'Puedes editar la información y cargar nuevas plantillas.';document.getElementById('approveDncBtn').hidden=approved;document.getElementById('reopenDncBtn').hidden=!approved;const issues=validateDncForFinal();document.getElementById('approvalIssues').innerHTML=issues.length?`Pendientes para aprobar: ${issues.slice(0,4).map(escapeHtml).join(' · ')}${issues.length>4?` · +${issues.length-4} más`:''}`:'Sin pendientes de validación.';
}
function renderImagePreview(id,src,empty){const el=document.getElementById(id);el.innerHTML=src?`<img src="${src}" alt="Vista previa">`:empty;}

function navigate(view){document.querySelectorAll('.view').forEach(v=>v.classList.remove('active'));document.querySelectorAll('.nav-item').forEach(v=>v.classList.remove('active'));document.getElementById(`view-${view}`)?.classList.add('active');document.querySelector(`.nav-item[data-view="${view}"]`)?.classList.add('active');const titles={inicio:'Panel de capacitación docente',periodos:'Períodos','dnc-introduccion':'DNC · Introducción','dnc-base-legal':'DNC · Base Legal','dnc-alineacion':'DNC · Alineación Institucional','dnc-metodologia':'DNC · Metodología',configuracion:'Configuración'};document.getElementById('pageTitle').textContent=titles[view]||'DOC-CAPA';window.scrollTo({top:0,behavior:'smooth'});}
function toast(message){const el=document.getElementById('toast');el.textContent=message;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),2800);}
function ensureEditable(){if(state.dncStatus==='approved'){toast('La DNC está aprobada. Reábrela antes de modificar información.');return false;}return true;}
function savePeriod(){if(!ensureEditable())return;const start=document.getElementById('periodStart').value,end=document.getElementById('periodEnd').value;if(!start||!end)return toast('Selecciona inicio y fin del período.');if(start>end)return toast('La fecha de inicio no puede ser posterior al fin.');state.period={start,end,id:`PER-${start}-${end}`};saveState();toast('Período guardado.');}

function downloadCareersTemplate(){const rows=[['CODIGO_CARRERA','CARRERA','ACTIVA'],['','Ejemplo de carrera','SI']];downloadAoA(rows,'Carreras',`Plantilla_Carreras_${state.period?.id||'Periodo'}.xlsx`);}
function downloadAoA(rows,sheet,filename){const ws=XLSX.utils.aoa_to_sheet(rows);ws['!cols']=rows[0].map(h=>({wch:Math.max(18,String(h).length+4)}));const wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,ws,sheet);XLSX.writeFile(wb,filename);}
function downloadJson(rows,sheet,filename){const ws=XLSX.utils.json_to_sheet(rows);const wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,ws,sheet);XLSX.writeFile(wb,filename);}
async function readExcel(file){const data=await file.arrayBuffer(),wb=XLSX.read(data),sheet=wb.Sheets[wb.SheetNames[0]];return XLSX.utils.sheet_to_json(sheet,{defval:''});}
async function importCareers(file){if(!ensureEditable())return;try{const rows=await readExcel(file),good=[],bad=[];rows.forEach((r,idx)=>{const name=String(r.CARRERA||'').trim();if(!name){bad.push({...r,FILA_EXCEL:idx+2,ERROR:'CARRERA es obligatoria'});return;}good.push({code:String(r.CODIGO_CARRERA||'').trim(),name,active:!['no','0','false','inactiva'].includes(normalized(r.ACTIVA||'si'))});});const map=new Map(state.careers.map(x=>[normalized(x.name),x]));good.forEach(x=>map.set(normalized(x.name),x));state.careers=[...map.values()].sort((a,b)=>a.name.localeCompare(b.name,'es'));saveState();showImportResult('careersImportResult',good.length,bad,()=>downloadJson(bad,'Corregir','Correccion_Carreras.xlsx'));}catch(e){console.error(e);toast('No se pudo leer la plantilla de carreras.');}}
function showImportResult(id,good,bad,download){const el=document.getElementById(id);if(!el)return;el.innerHTML=`<div class="info-box">${good} fila(s) válida(s). ${bad.length?`${bad.length} con error. <button class="text-button correction-btn">Descargar plantilla de corrección</button>`:'Sin errores.'}</div>`;if(bad.length)el.querySelector('.correction-btn').onclick=download;}

function downloadSourceTemplate(key){const d=SOURCE_DEFS[key],example={};d.columns.forEach(c=>example[c]='');if(key==='surveys'){example.CARRERA='Ejemplo de carrera';example.NECESIDAD='Metodologías activas';example.RESPUESTA='Necesidad identificada';}if(key==='meetings'){example.CARRERA='Ejemplo de carrera';example.FECHA_REUNION='2026-01-15';example.NECESIDAD='Metodologías activas';}if(key==='coordinators'){example.CARRERA='Ejemplo de carrera';example.COORDINADOR='Nombre del coordinador';example.NECESIDAD_VALIDADA='Metodologías activas';example.DESEMPATE_REQUERIDO='NO';}if(key==='curricula'){example.CARRERA='Ejemplo de carrera';example.NECESIDAD='Actualización disciplinar';example.HALLAZGO='Hallazgo curricular';}if(key==='peas'){example.CARRERA='Ejemplo de carrera';example.NECESIDAD='Evaluación por resultados';example.HALLAZGO='Hallazgo PEA';}downloadJson([example],d.sheet,`Plantilla_${d.sheet}_${state.period?.id||'Periodo'}.xlsx`);}
function sourceRowCareerValid(name){return activeCareers().some(c=>normalized(c.name)===normalized(name));}
async function importSource(key,file){if(!ensureEditable())return;const d=SOURCE_DEFS[key];try{const rows=await readExcel(file),good=[],bad=[];rows.forEach((r,idx)=>{const missing=d.required.filter(f=>!String(r[f]??'').trim());if(missing.length){bad.push({...r,FILA_EXCEL:idx+2,ERROR:`Falta: ${missing.join(', ')}`});return;}if(!sourceRowCareerValid(r.CARRERA)){bad.push({...r,FILA_EXCEL:idx+2,ERROR:'CARRERA no existe o no está activa en el período'});return;}const clean={};d.columns.forEach(c=>clean[c]=String(r[c]??'').trim());good.push(clean);});const identity=r=>`${normalized(r.CARRERA)}|${normalized(sourceNeed(r,key))}|${normalized(r.FECHA_REUNION||r.COORDINADOR||r.ID_DOCENTE||r.HALLAZGO||r.RESPUESTA||'')}`;const map=new Map(state.sources[key].map(r=>[identity(r),r]));good.forEach(r=>map.set(identity(r),r));state.sources[key]=[...map.values()];saveState();showImportResult(`import-${key}`,good.length,bad,()=>downloadJson(bad,'Corregir',`Correccion_${d.sheet}.xlsx`));toast(`${d.label}: ${good.length} fila(s) procesada(s).`);}catch(e){console.error(e);toast(`No se pudo leer ${d.label}.`);}}

function downloadCandidatesTemplate(){const rows=[];if(activeCareers().length){activeCareers().forEach(c=>{for(let i=1;i<=5;i++)rows.push({CARRERA:c.name,NOMBRE_NECESIDAD:'',IMPACTO_ACADEMICO:'Pendiente',PERTINENCIA_CURRICULAR:'Pendiente',ALINEACION_INSTITUCIONAL:'Pendiente',PRELIMINAR:'NO',VALIDACION_COORDINADOR:'Pendiente',GANADORA:'NO'});});}else rows.push({CARRERA:'Ejemplo de carrera',NOMBRE_NECESIDAD:'Necesidad de capacitación',IMPACTO_ACADEMICO:'Alto',PERTINENCIA_CURRICULAR:'Alto',ALINEACION_INSTITUCIONAL:'Alto',PRELIMINAR:'NO',VALIDACION_COORDINADOR:'Pendiente',GANADORA:'NO'});downloadJson(rows,'Candidatas',`Plantilla_Necesidades_Candidatas_${state.period?.id||'Periodo'}.xlsx`);}
async function importCandidates(file){if(!ensureEditable())return;try{const rows=await readExcel(file),good=[],bad=[],counts={};rows.forEach((r,idx)=>{const career=String(r.CARRERA||'').trim(),need=String(r.NOMBRE_NECESIDAD||'').trim();if(!career||!need){bad.push({...r,FILA_EXCEL:idx+2,ERROR:'CARRERA y NOMBRE_NECESIDAD son obligatorios'});return;}if(!sourceRowCareerValid(career)){bad.push({...r,FILA_EXCEL:idx+2,ERROR:'CARRERA no existe o no está activa'});return;}const ck=normalized(career);counts[ck]=(counts[ck]||0)+1;if(counts[ck]>5){bad.push({...r,FILA_EXCEL:idx+2,ERROR:'Máximo 5 necesidades candidatas por carrera'});return;}if(!evidenceForNeed(career,need).length){bad.push({...r,FILA_EXCEL:idx+2,ERROR:'La necesidad no coincide con evidencia cargada en ninguna fuente'});return;}good.push({CARRERA:career,NOMBRE_NECESIDAD:need,IMPACTO_ACADEMICO:String(r.IMPACTO_ACADEMICO||'Pendiente').trim(),PERTINENCIA_CURRICULAR:String(r.PERTINENCIA_CURRICULAR||'Pendiente').trim(),ALINEACION_INSTITUCIONAL:String(r.ALINEACION_INSTITUCIONAL||'Pendiente').trim(),PRELIMINAR:boolValue(r.PRELIMINAR),VALIDACION_COORDINADOR:String(r.VALIDACION_COORDINADOR||'Pendiente').trim(),GANADORA:boolValue(r.GANADORA)});});const grouped=new Map();state.candidates.forEach(r=>grouped.set(`${normalized(r.CARRERA)}|${normalized(r.NOMBRE_NECESIDAD)}`,r));good.forEach(r=>grouped.set(`${normalized(r.CARRERA)}|${normalized(r.NOMBRE_NECESIDAD)}`,r));state.candidates=[...grouped.values()];normalizeCandidateFlags();saveState();showImportResult('candidatesImportResult',good.length,bad,()=>downloadJson(bad,'Corregir','Correccion_Necesidades_Candidatas.xlsx'));}catch(e){console.error(e);toast('No se pudo leer la plantilla de necesidades candidatas.');}}
function normalizeCandidateFlags(){activeCareers().forEach(c=>{const rows=careerCandidates(c.name);const prelim=rows.filter(r=>r.PRELIMINAR);if(prelim.length>1)prelim.slice(1).forEach(r=>{r.PRELIMINAR=false;r.GANADORA=false;});const winners=rows.filter(r=>r.GANADORA);if(winners.length>1)winners.slice(1).forEach(r=>r.GANADORA=false);rows.forEach(r=>{if(r.GANADORA&&(!r.PRELIMINAR||normalized(r.VALIDACION_COORDINADOR)!=='si'))r.GANADORA=false;});});}

function saveInstitutionalConfig(){if(!ensureEditable())return;const oldModel=state.institutionalConfig.cacesModel,newModel=document.getElementById('configCacesModel').value.trim();state.institutionalConfig={...state.institutionalConfig,pedi:document.getElementById('configPedi').value.trim(),poa:document.getElementById('configPoa').value.trim(),manual:document.getElementById('configManual').value.trim(),cacesModel:newModel,cacesYear:document.getElementById('configCacesYear').value.trim(),surveyTool:document.getElementById('configSurveyTool').value.trim()||'Microsoft Forms'};if(normalized(oldModel)!==normalized(newModel))state.institutionalConfig.cacesValidated=false;saveState();toast('Configuración institucional guardada.');}
function validateCaces(){if(!ensureEditable())return;if(!state.institutionalConfig.cacesModel)return toast('Configura primero el Modelo CACES vigente.');state.institutionalConfig.cacesValidated=true;saveState();toast('Bloque CACES marcado como validado.');}
function handleImage(file,target){if(!ensureEditable()||!file)return;const reader=new FileReader();reader.onload=()=>{if(target==='logo')state.logo=reader.result;else state.methodologyImages[target]=reader.result;saveState();toast('Imagen guardada en la configuración.');};reader.readAsDataURL(file);}

function approveDnc(){const errors=validateDncForFinal();if(errors.length){toast(`No se puede aprobar: ${errors[0]}`);return;}state.dncStatus='approved';saveState();toast('DNC aprobada y cerrada.');}
function reopenDnc(){state.dncStatus='draft';saveState();toast('DNC reabierta para edición.');}

function buildPrintDocument(){const period=state.period?periodLabel():'Período pendiente',logo=state.logo?`<img src="${state.logo}" alt="Logo">`:'<span class="rgi-logo-placeholder">LOGOTIPO<br>ITSQMET</span>';return`<section class="doc-cover"><div class="rgi-head"><div class="rgi-logo">${logo}</div><div class="rgi-center"><div class="rgi-unit">Unidad de Gestión de Procesos Académicos</div><div class="rgi-doc">Detección de Necesidades de Capacitación<br>${escapeHtml(period)}</div></div><div class="rgi-code"><div><strong>Código:</strong><br>UGPA-RGI1-01-PRO-70-<br>${state.period?state.period.start:'AAAA-MM'}</div></div></div><div class="cover-title"><h1>Detección de Necesidades de Capacitación</h1><h2>${escapeHtml(period)}</h2></div><div class="signature-grid">${signatureColumn('ELABORADO POR:','Mgs. Jefferson Villarreal','Gestor de Procesos Académicos')}${signatureColumn('REVISADO POR:','Ing. Martha Tomalá','Coordinadora General de Carreras')}${signatureColumn('APROBADO POR:','Dr. Alex León','Vicerrector')}</div></section><section class="doc-content doc-page">${renderIntroHtml()}</section><section class="doc-content doc-page">${renderLegalHtml()}</section><section class="doc-content doc-page">${renderAlignmentHtml()}</section><section class="doc-content doc-page">${renderMethodHtml()}</section>`;}
function signatureColumn(label,name,role){return`<div class="signature-col"><div class="signature-space">${label}</div><div><strong>NOMBRE:</strong> ${escapeHtml(name)}</div><div><strong>CARGO:</strong> ${escapeHtml(role)}</div></div>`;}
function openPreview(){document.getElementById('printDocument').innerHTML=buildPrintDocument();document.getElementById('pdfPreviewDialog').showModal();}
function closePreview(){document.getElementById('pdfPreviewDialog').close();}

function writeHeading(doc,text,level,y){const size=level===2?13:level===3?11:10;if(y>275){doc.addPage();y=18;}doc.setFont('helvetica','bold');doc.setFontSize(size);doc.text(text,15,y);return y+(level===2?7:6);}
function writeParagraph(doc,text,y){doc.setFont('helvetica','normal');doc.setFontSize(9.5);const lines=doc.splitTextToSize(String(text),180);for(const line of lines){if(y>280){doc.addPage();y=18;}doc.text(line,15,y,{maxWidth:180});y+=4.6;}return y+2.5;}
function writeBulletList(doc,items,y){items.forEach(x=>{if(y>278){doc.addPage();y=18;}doc.setFont('helvetica','normal');doc.setFontSize(9.5);doc.text('•',18,y);const lines=doc.splitTextToSize(x,170);lines.forEach((line,j)=>{if(y>280){doc.addPage();y=18;}doc.text(line,24,y);y+=4.6;});y+=1;});return y;}
function addImageBlock(doc,src,y){if(!src)return y;try{if(y>220){doc.addPage();y=18;}const props=doc.getImageProperties(src),maxW=160,maxH=70,ratio=Math.min(maxW/props.width,maxH/props.height),w=props.width*ratio,h=props.height*ratio;doc.addImage(src,'PNG',105-w/2,y,w,h,undefined,'FAST');return y+h+6;}catch{return y;}}
function drawRgiHeader(doc,period){const x=15,y=15,h1=8,h2=20;doc.setDrawColor(0);doc.setLineWidth(.25);doc.rect(x,y,45,h1+h2);doc.rect(x+45,y,90,h1);doc.rect(x+45,y+h1,90,h2);doc.rect(x+135,y,45,h1+h2);if(state.logo){try{doc.addImage(state.logo,'PNG',x+4,y+4,37,18,undefined,'FAST');}catch{}}else{doc.setFont('helvetica','bold');doc.setFontSize(9);doc.text('ITSQMET',x+22.5,y+14,{align:'center'});}doc.setFont('helvetica','bold');doc.setFontSize(9);doc.text('Unidad de Gestión de Procesos Académicos',x+90,y+5.2,{align:'center'});doc.setFontSize(8.5);doc.text('Detección de Necesidades de Capacitación',x+90,y+14,{align:'center'});doc.setFont('helvetica','normal');doc.setFontSize(8);doc.text(period,x+90,y+20,{align:'center'});doc.setFontSize(7.5);doc.text(['Código:','UGPA-RGI1-01-PRO-70-',state.period?state.period.start:'AAAA-MM'],x+157.5,y+10,{align:'center'});}
function drawCover(doc){const period=state.period?periodLabel():'Período pendiente';drawRgiHeader(doc,period);doc.setFont('helvetica','bold');doc.setFontSize(18);doc.text('Detección de Necesidades de Capacitación',105,132,{align:'center'});doc.setFontSize(16);doc.text(period,105,144,{align:'center'});const y=238,x=15,col=60;doc.rect(x,y,180,42);doc.line(x+col,y,x+col,y+42);doc.line(x+col*2,y,x+col*2,y+42);doc.line(x,y+24,x+180,y+24);doc.line(x,y+31.5,x+180,y+31.5);const rows=[['ELABORADO POR:','Mgs. Jefferson Villarreal','Gestor de Procesos Académicos'],['REVISADO POR:','Ing. Martha Tomalá','Coordinadora General de Carreras'],['APROBADO POR:','Dr. Alex León','Vicerrector']];rows.forEach((r,i)=>{const cx=x+i*col+2;doc.setFontSize(7.5);doc.setFont('helvetica','bold');doc.text(r[0],cx,y+5);doc.text('NOMBRE:',cx,y+29);doc.text('CARGO:',cx,y+36);doc.setFont('helvetica','normal');doc.text(r[1],cx+14,y+29);doc.text(doc.splitTextToSize(r[2],42),cx+12,y+36);});}
function writeIntroPdf(doc){let y=20;y=writeHeading(doc,'1. Introducción',2,y);y=writeHeading(doc,'1.1. Justificación del Informe',3,y);INTRO.justification.forEach(p=>y=writeParagraph(doc,p,y));y=writeHeading(doc,'1.2. Alcance Temporal y Cobertura',3,y);introScopeParagraphs().forEach(p=>y=writeParagraph(doc,p,y));y=writeHeading(doc,'1.3. Contexto Institucional y Transformaciones Educativas',3,y);INTRO.contextIntro.forEach(p=>y=writeParagraph(doc,p,y));INTRO.transformations.forEach(([t,ps])=>{y=writeHeading(doc,t,4,y);ps.forEach(p=>y=writeParagraph(doc,p,y));});y=writeHeading(doc,'1.4. Objetivos del Diagnóstico',3,y);INTRO.objectivesIntro.forEach(p=>y=writeParagraph(doc,p,y));y=writeHeading(doc,'1.4.1. Objetivo General',4,y);y=writeParagraph(doc,INTRO.generalObjective,y);y=writeHeading(doc,'1.4.2. Objetivos Específicos',4,y);INTRO.specificObjectives.forEach((p,i)=>y=writeParagraph(doc,`${String.fromCharCode(97+i)}) ${p}`,y));}
function writeLegalPdf(doc){let y=20;y=writeHeading(doc,'2. Base Legal',2,y);LEGAL.intro.forEach(p=>y=writeParagraph(doc,p,y));LEGAL.blocks.forEach(b=>{y=writeHeading(doc,b.title,4,y);b.items.forEach(item=>{if(y>278){doc.addPage();y=18;}doc.setFont('helvetica','italic');doc.setFontSize(9.5);doc.text('Que,',15,y);doc.setFont('helvetica','normal');const lines=doc.splitTextToSize(item,165);lines.forEach(line=>{if(y>280){doc.addPage();y=18;}doc.text(line,30,y);y+=4.6;});y+=1.8;});});writeParagraph(doc,LEGAL.closing,y);}
function writeAlignmentPdf(doc){const cfg=state.institutionalConfig;let y=20;y=writeHeading(doc,'3. Alineación Institucional',2,y);ALIGNMENT.intro.forEach(p=>y=writeParagraph(doc,p,y));[ALIGNMENT.pedi,ALIGNMENT.poa,ALIGNMENT.manual].forEach(b=>{y=writeHeading(doc,b.title,3,y);b.intro(cfg).forEach(p=>y=writeParagraph(doc,p,y));b.blocks.forEach(([t,p])=>{y=writeHeading(doc,t,4,y);y=writeParagraph(doc,p,y);});y=writeParagraph(doc,b.closing,y);});y=writeHeading(doc,CACES_BLOCK.title,3,y);CACES_BLOCK.intro(cfg).forEach(p=>y=writeParagraph(doc,p,y));CACES_BLOCK.sections.forEach(s=>{y=writeHeading(doc,s.heading,4,y);s.paragraphs.forEach(p=>y=writeParagraph(doc,p,y));if(s.lists?.[0])y=writeBulletList(doc,s.lists[0],y);if(s.bridge){y=writeParagraph(doc,s.bridge,y);if(s.lists?.[1])y=writeBulletList(doc,s.lists[1],y);}if(s.closing)y=writeParagraph(doc,s.closing,y);});}
function writeMethodPdf(doc){const cfg=state.institutionalConfig,period=state.period?periodLabel():'[PERÍODO ACADÉMICO PENDIENTE]';let y=20;y=writeHeading(doc,'4. Metodología del Diagnóstico',2,y);y=addImageBlock(doc,state.methodologyImages.diagnostic,y);y=writeHeading(doc,'4.1. Enfoque Diagnóstico de la Investigación',3,y);y=writeParagraph(doc,METHOD_TEXT.opening,y);y=writeHeading(doc,'A) Tipo de enfoque',4,y);y=writeParagraph(doc,METHOD_TEXT.typeIntro,y);y=writeBulletList(doc,[METHOD_TEXT.quantitative(cfg.surveyTool),METHOD_TEXT.qualitative],y);y=writeHeading(doc,'B) Nivel del estudio',4,y);y=writeParagraph(doc,METHOD_TEXT.level,y);y=writeHeading(doc,'C) Finalidad del diagnóstico',4,y);y=writeParagraph(doc,METHOD_TEXT.purpose,y);y=writeHeading(doc,'D) Unidad de análisis',4,y);y=writeParagraph(doc,METHOD_TEXT.unit,y);y=writeHeading(doc,'E) Temporalidad',4,y);y=writeParagraph(doc,METHOD_TEXT.temporal(period),y);y=writeHeading(doc,'F) Rol del diagnóstico en el ciclo institucional',4,y);y=writeParagraph(doc,METHOD_TEXT.role,y);y=writeHeading(doc,'G) Articulación con la planificación y aseguramiento de la calidad',4,y);y=writeParagraph(doc,METHOD_TEXT.quality(cfg),y);y=writeHeading(doc,'4.2. Fuentes de Información',3,y);METHOD_TEXT.sourcesIntro.forEach(p=>y=writeParagraph(doc,p,y));y=addImageBlock(doc,state.methodologyImages.sources,y);y=writeHeading(doc,'A) Fuentes primarias',4,y);[['surveys','1.'],['meetings','2.'],['coordinators','3.']].forEach(([k,n])=>{y=writeHeading(doc,`${n} ${SOURCE_DEFS[k].label}`,4,y);y=writeParagraph(doc,hasSource(k)?SOURCE_DEFS[k].description:sourceAvailabilityText(k),y);if(hasSource(k)&&SOURCE_DEFS[k].bullets.length)y=writeBulletList(doc,SOURCE_DEFS[k].bullets,y);});y=writeHeading(doc,'B) Fuentes secundarias',4,y);[['curricula','1.'],['peas','2.']].forEach(([k,n])=>{y=writeHeading(doc,`${n} ${SOURCE_DEFS[k].label}`,4,y);y=writeParagraph(doc,hasSource(k)?SOURCE_DEFS[k].description:sourceAvailabilityText(k),y);if(hasSource(k)&&SOURCE_DEFS[k].bullets.length)y=writeBulletList(doc,SOURCE_DEFS[k].bullets,y);});y=writeHeading(doc,'C) Enfoque de análisis y complementariedad de fuentes',4,y);METHOD_TEXT.complement.forEach(p=>y=writeParagraph(doc,p,y));y=writeHeading(doc,'D) Uso de las fuentes en el proceso diagnóstico',4,y);y=writeParagraph(doc,METHOD_TEXT.use,y);y=writeBulletList(doc,METHOD_TEXT.useBullets,y);y=writeHeading(doc,'E) Articulación institucional y aseguramiento de la calidad',4,y);y=writeParagraph(doc,METHOD_TEXT.sourcesQuality,y);y=writeHeading(doc,'4.2.1. Criterio del Coordinador de Carrera',3,y);y=writeParagraph(doc,hasSource('coordinators')?'El criterio del coordinador contrasta y valida información, complementa otras fuentes y puede apoyar un desempate; no reemplaza los datos de encuestas ni selecciona arbitrariamente una necesidad.':sourceAvailabilityText('coordinators'),y);y=writeHeading(doc,'4.2.2. Reuniones Académicas con Docentes',3,y);y=writeParagraph(doc,hasSource('meetings')?'Las reuniones académicas recopilan información cualitativa sobre metodologías de enseñanza, actualización disciplinar y pedagógica, dificultades de implementación de los PEA y necesidades relacionadas con herramientas y recursos educativos.':sourceAvailabilityText('meetings'),y);y=writeHeading(doc,'4.2.3. Encuestas Institucionales',3,y);y=writeParagraph(doc,hasSource('surveys')?`Las encuestas institucionales fueron aplicadas mediante ${cfg.surveyTool}, permitiendo una recolección de información estructurada, sistemática y estandarizada.`:sourceAvailabilityText('surveys'),y);y=writeHeading(doc,'4.3. Criterios para la Identificación y Priorización de Necesidades',3,y);y=writeParagraph(doc,'Por cada carrera se identifican cinco necesidades de capacitación obtenidas del análisis integrado de las fuentes disponibles.',y);y=writeBulletList(doc,['Impacto en la calidad de la docencia.','Pertinencia con la carrera.','Recurrencia de la necesidad.','Alineación institucional.'],y);y=writeParagraph(doc,'El procedimiento no establece una fórmula matemática ni pesos numéricos específicos; la aplicación no utiliza una ponderación inventada.',y);y=writeHeading(doc,'4.4. Procedimiento para la Selección de la Necesidad Ganadora',3,y);['A) Identificación preliminar de necesidades por carrera|Fuentes disponibles → análisis → cinco necesidades candidatas.','B) Sistematización y contraste de información|Cada necesidad se relaciona con evidencia proveniente de una o más fuentes.','C) Análisis del impacto académico|Cada una de las cinco necesidades se analiza considerando su incidencia en el proceso de enseñanza-aprendizaje, el logro de resultados de aprendizaje y la coherencia curricular y metodológica.','D) Validación académica|La necesidad preliminar prioritaria se somete a validación del coordinador de carrera y no puede cerrarse como ganadora si la validación permanece pendiente.','E) Selección de la necesidad ganadora|Después del análisis y validación se registra la necesidad ganadora por carrera.','F) Registro del resultado del procedimiento|La necesidad ganadora queda asociada al período y a la carrera para su utilización posterior en el Plan de Capacitación Docente.'].forEach(s=>{const[t,p]=s.split('|');y=writeHeading(doc,t,4,y);y=writeParagraph(doc,p,y);});}
function downloadPdf(){if(!jsPDF)return toast('No se cargó el generador PDF.');const errors=validateDncForFinal();if(errors.length&&state.dncStatus!=='approved')toast(`PDF de trabajo: ${errors[0]}`);const doc=new jsPDF({unit:'mm',format:'a4',orientation:'portrait'});drawCover(doc);doc.addPage();writeIntroPdf(doc);doc.addPage();writeLegalPdf(doc);doc.addPage();writeAlignmentPdf(doc);doc.addPage();writeMethodPdf(doc);doc.save(`DNC_ITSQMET_${state.period?`${state.period.start}_${state.period.end}`:'BORRADOR'}.pdf`);}

function bindEvents(){document.querySelectorAll('[data-view]').forEach(b=>b.addEventListener('click',()=>navigate(b.dataset.view)));document.querySelectorAll('[data-go]').forEach(b=>b.addEventListener('click',()=>navigate(b.dataset.go)));document.getElementById('savePeriodBtn').addEventListener('click',savePeriod);document.getElementById('downloadCareersTemplateBtn').addEventListener('click',downloadCareersTemplate);document.getElementById('careersFileInput').addEventListener('change',e=>e.target.files[0]&&importCareers(e.target.files[0]));document.querySelectorAll('[data-template]').forEach(b=>b.addEventListener('click',()=>downloadSourceTemplate(b.dataset.template)));document.querySelectorAll('[data-source]').forEach(i=>i.addEventListener('change',e=>e.target.files[0]&&importSource(i.dataset.source,e.target.files[0])));document.getElementById('downloadCandidatesTemplateBtn').addEventListener('click',downloadCandidatesTemplate);document.getElementById('candidatesFileInput').addEventListener('change',e=>e.target.files[0]&&importCandidates(e.target.files[0]));document.getElementById('saveInstitutionalConfigBtn').addEventListener('click',saveInstitutionalConfig);document.getElementById('validateCacesBtn').addEventListener('click',validateCaces);document.getElementById('logoInput').addEventListener('change',e=>handleImage(e.target.files[0],'logo'));document.getElementById('removeLogoBtn').addEventListener('click',()=>{if(!ensureEditable())return;state.logo=null;saveState();});document.getElementById('methodImageDiagnosticInput').addEventListener('change',e=>handleImage(e.target.files[0],'diagnostic'));document.getElementById('methodImageSourcesInput').addEventListener('change',e=>handleImage(e.target.files[0],'sources'));document.getElementById('removeMethodImageDiagnosticBtn').addEventListener('click',()=>{if(!ensureEditable())return;state.methodologyImages.diagnostic=null;saveState();});document.getElementById('removeMethodImageSourcesBtn').addEventListener('click',()=>{if(!ensureEditable())return;state.methodologyImages.sources=null;saveState();});document.getElementById('approveDncBtn').addEventListener('click',approveDnc);document.getElementById('reopenDncBtn').addEventListener('click',reopenDnc);document.getElementById('previewDncBtn').addEventListener('click',openPreview);document.getElementById('previewLegalBtn').addEventListener('click',openPreview);document.getElementById('previewMethodBtn').addEventListener('click',openPreview);document.getElementById('downloadDncBtn').addEventListener('click',downloadPdf);document.getElementById('downloadFromPreviewBtn').addEventListener('click',downloadPdf);document.getElementById('closePreviewBtn').addEventListener('click',closePreview);document.getElementById('closePreviewBottomBtn').addEventListener('click',closePreview);}

bindEvents();renderAll();